// BashSharpLexerInit initializes any static state used to implement BashSharpLexer. By default the
// static state used to implement the lexer is lazily initialized during the first call to
// NewBashSharpLexer(). You can call this function if you wish to initialize the static state ahead
// of time.
func BashSharpLexerInit() {
	staticData := &BashSharpLexerLexerStaticData
	staticData.once.Do(bashsharplexerLexerInit)
}

// NewBashSharpLexer produces a new lexer instance for the optional input antlr.CharStream.
func NewBashSharpLexer(input antlr.CharStream) *BashSharpLexer {
	BashSharpLexerInit()
	l := new(BashSharpLexer)
	l.BaseLexer = antlr.NewBaseLexer(input)
	staticData := &BashSharpLexerLexerStaticData
	l.Interpreter = antlr.NewLexerATNSimulator(l, staticData.atn, staticData.decisionToDFA, staticData.PredictionContextCache)
	l.channelNames = staticData.ChannelNames
	l.modeNames = staticData.ModeNames
	l.RuleNames = staticData.RuleNames
	l.LiteralNames = staticData.LiteralNames
	l.SymbolicNames = staticData.SymbolicNames
	l.GrammarFileName = "BashSharpLexer.g4"
	// TODO: l.EOF = antlr.TokenEOF

	return l
}

