func (l *BashSharpLexer) Action(localctx antlr.RuleContext, ruleIndex, actionIndex int) {
	switch ruleIndex {
	case 3:
		l.L_CURLY_Action(localctx, actionIndex)

	case 101:
		l.GO_EOS_Action(localctx, actionIndex)

	case 112:
		l.FENCE_OPEN_Action(localctx, actionIndex)

	case 139:
		l.WORD_Action(localctx, actionIndex)

	case 161:
		l.HEREDOC_LINE_Action(localctx, actionIndex)

	case 162:
		l.FENCE_LINE_Action(localctx, actionIndex)

	default:
		panic("No registered action for: " + fmt.Sprint(ruleIndex))
	}
}

