func (l *BashSharpLexer) Sempred(localctx antlr.RuleContext, ruleIndex, predIndex int) bool {
	switch ruleIndex {
	case 110:
		return l.SH_COMMENT_Sempred(localctx, predIndex)

	case 111:
		return l.SH_SLASH_COMMENT_Sempred(localctx, predIndex)

	case 112:
		return l.FENCE_OPEN_Sempred(localctx, predIndex)

	case 113:
		return l.ARITH_CMD_Sempred(localctx, predIndex)

	case 114:
		return l.ARRAY_ASSIGN_Sempred(localctx, predIndex)

	case 138:
		return l.IO_NUMBER_Sempred(localctx, predIndex)

	case 149:
		return l.DOLLAR_Sempred(localctx, predIndex)

	case 150:
		return l.DQ_DOLLAR_Sempred(localctx, predIndex)

	default:
		panic("No registered predicate for: " + fmt.Sprint(ruleIndex))
	}
}

